// ─── File: src/main/java/com/nbi/boundary/model/Customer.java ───
package com.nbi.boundary.model;

// ENTITY: holds SECRET + internal columns. NEVER returned to clients.
public class Customer {
    private String id;
    private String name;
    private String passwordHash;  // secret → must not leak
    private int fraudRiskScore;   // internal only

    public Customer(String id, String name, String passwordHash, int fraudRiskScore) {
        this.id = id; this.name = name;
        this.passwordHash = passwordHash; this.fraudRiskScore = fraudRiskScore;
    }
    public String getId() { return id; }
    public String getName() { return name; }
    public String getPasswordHash() { return passwordHash; }
    public int getFraudRiskScore() { return fraudRiskScore; }
}
```

