// ─── File: src/main/java/com/nbi/boundary/model/Account.java ───
package com.nbi.boundary.model;

import java.math.BigDecimal;
import java.util.*;

// ENTITY with a LAZY relationship that would throw if serialised after tx close.
public class Account {
    private String id;
    private String holderName;
    private BigDecimal balance;
    private BigDecimal pendingHolds;
    private List<String> lazyTxns; // simulate lazy: only "load" when explicitly fetched

    public Account(String id, String holderName, BigDecimal balance, BigDecimal pendingHolds) {
        this.id = id; this.holderName = holderName;
        this.balance = balance; this.pendingHolds = pendingHolds;
        this.lazyTxns = null; // not loaded
    }
    public String getId() { return id; }
    public String getHolderName() { return holderName; }
    public BigDecimal getBalance() { return balance; }
    public BigDecimal getPendingHolds() { return pendingHolds; }
    public List<String> getLazyTxns() {
        if (lazyTxns == null) throw new IllegalStateException("LazyInitializationException");
        return lazyTxns;
    }
}
