// ─── File: src/main/java/com/nbi/boundary/service/CustomerService.java ───
package com.nbi.boundary.service;

import com.nbi.boundary.dto.*;
import com.nbi.boundary.model.*;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;

@Service
public class CustomerService {
    private final Map<String, Customer> customers = new HashMap<>();
    private final Map<String, Account> accounts = new HashMap<>();

    public CustomerService() {
        customers.put("CUST-1", new Customer("CUST-1", "Rajesh Kumar", "hash$secret", 42));
        accounts.put("SAV2001", new Account("SAV2001", "Rajesh Kumar",
                new BigDecimal("1000000.00"), new BigDecimal("50000.00")));
    }

    // Map entity → safe DTO: secrets simply not copied.
    public Optional<CustomerResponse> getCustomer(String id) {
        return Optional.ofNullable(customers.get(id))
                .map(c -> new CustomerResponse(c.getId(), c.getName())); // no secrets
    }

    // Map INSIDE the service (within tx) → never touch lazy fields in the serialiser.
    public Optional<AccountResponseV1> getAccountV1(String id) {
        return Optional.ofNullable(accounts.get(id))
                .map(a -> new AccountResponseV1(a.getId(), a.getHolderName(), a.getBalance()));
        // we never call getLazyTxns() → no LazyInitializationException
    }

    public Optional<AccountResponseV2> getAccountV2(String id) {
        return Optional.ofNullable(accounts.get(id)).map(a -> new AccountResponseV2(
                a.getId(), a.getHolderName(), a.getBalance(),
                a.getBalance().subtract(a.getPendingHolds()))); // computed field
    }
}
```

