// ─── File: src/main/java/com/nbi/boundary/controller/CustomerController.java ───
package com.nbi.boundary.controller;

import com.nbi.boundary.service.CustomerService;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

@RestController
public class CustomerController {

    private final CustomerService service;
    public CustomerController(CustomerService service) { this.service = service; }

    @GetMapping("/api/v1/customers/{id}")
    public ResponseEntity<?> customer(@PathVariable String id) {
        return service.getCustomer(id).map(ResponseEntity::ok)
                .orElse(ResponseEntity.notFound().build());
    }

    // Same entity, two API versions via two DTOs.
    @GetMapping("/api/v1/accounts/{id}")
    public ResponseEntity<?> accountV1(@PathVariable String id) {
        return service.getAccountV1(id).map(ResponseEntity::ok)
                .orElse(ResponseEntity.notFound().build());
    }

    @GetMapping("/api/v2/accounts/{id}")
    public ResponseEntity<?> accountV2(@PathVariable String id) {
        return service.getAccountV2(id).map(ResponseEntity::ok)
                .orElse(ResponseEntity.notFound().build());
    }
}
